\begin{tikzpicture}[every node/.style={font=\large}, scale=0.55]
\usetikzlibrary{arrows.meta}
\draw[step=1,gray!25,very thin] (-6,-4) grid (1,2);
\draw[->] (-6.4,0)--(1.4,0) node[right]{$x$};
\draw[->] (0,-4.4)--(0,2.4) node[above]{$y$};
\foreach \i in {-6,-4,-2} \node[above,font=\scriptsize] at (\i,0){$\i$};
\foreach \i in {-4,-2,2} \node[right,font=\scriptsize] at (0,\i){$\i$};
\draw[-{Stealth},thick,blue] (0,0)--(-5,-3);
\end{tikzpicture}
[/tikz]
